                cnt.globalSettings?.remove("contents." + ixsFun + ".SlozkyVypoctene#.SlozkyVypoctene");
                cnt.globalSettings?.remove("contents." + ixsFun + ".SlozkyMzm#.SlozkyMzm");
                cnt.globalSettings?.remove("contents." + ixsFun + ".SlozkyDnp#.SlozkyDnp");
                cnt.globalSettings?.remove("contents." + ixsFun + ".Srazky#.Srazky");
                cnt.globalSettings?.remove("contents." + ixsFun + ".VyctovePersonalniUdaje#.VyctovePersonalniUdaje");
                cnt.globalSettings?.remove("contents." + ixsFun + ".HodnotovePersonalniUdaje#.HodnotovePersonalniUdaje");
                cnt.globalSettings?.remove("contents." + ixsFun + ".AdresyOsob#.AdresyOsob");
                cnt.globalSettings?.remove("contents." + ixsFun + ".KategorieSystMista#.KategorieSystMista");
