                            that.SouhrnAktivnichFiltruJednotlive = WebApp.SouhrnAktivnichFiltruJednotlive(that, true, false, false, that.ixs_mas);
                            that.SouhrnAktivnichFiltruJednotliveP = that.SouhrnAktivnichFiltruJednotlive.gFiltrDtos ?? [];
