                                // všechny řádky gridu (bez meta) původní zdroj dat
                                //const vsechny: Pam.Interface.GStromUzelDto[] = seznam.ggrid("getView").getDataRows(false,"data")
                                //that.userSettings?.set(that.idFiltru+"Cely", vsechny)
                                // nastaví odznáček na menu s počtem vybraných filtrů
                                that.pocetRadku = that.userSettings?.get(that.idFiltru)?.length;
                                if (that.pocetRadku > 0) {
                                    Gordic.Pam.Actions.nastavOdznacekMenu(that, that.taskId, that.pocetRadku.toString(), "jres:27880257"); //RC 27880257 : Počet vybraných filtrů
                                }
                                else {
                                    Gordic.Pam.Actions.nastavOdznacekMenu(that, that.taskId, "", "");
                                }
                                // počet ukládaných řádků
                                const pocet = that.dtoUlozeneUzly.length;
