                            const filtry = WebApp.SouhrnAktivnichFiltruJednotlive(that, true, false, true);
                            let jeChybaStromu = false;
                            let jeChybaObdobi1 = false;
                            // kontrola, jestli je výchozí strom (je vybraný alespoň jeden uzel stromu)
                            const vychoziStrom = filtry.gFiltrDtos?.find(x => x.filtr == "VychoziStrom#")?.hodnota ?? "";
                            jeChybaStromu = (vychoziStrom != "UUS" && vychoziStrom != "OCE" && vychoziStrom != "SNK");
                            // kontrola na období první
                            const obdobiOd = Number(filtry.gFiltrDtos?.find(x => x.filtr == "Obdobi#rok_obd_od")?.klic) ?? that.rokobdmzdy;
                            const obdobiDo = Number(filtry.gFiltrDtos?.find(x => x.filtr == "Obdobi#rok_obd_do")?.klic) ?? that.rokobdmzdy;
                            jeChybaObdobi1 = (obdobiDo > that.rokobdmzdy || obdobiOd > that.rokobdmzdy); // chyba, když období do > přihlášení nebo od > období přihlášení
